const filingPath='admin/ims/filing/';let filingFolder=null;
async function filingView(v){const t=await api(filingPath+'tree');if(tab!=='filing')return;if(!t.folders.some(f=>String(f.id)===String(filingFolder)))filingFolder=null;const selected=t.folders.find(f=>String(f.id)===String(filingFolder));const rows=selected?await api(filingPath+'folders/'+selected.id+'/files'):[];if(tab!=='filing')return;const children=(parent=null,level=0)=>level>50?'':t.folders.filter(f=>String(f.parent_id??'')===String(parent??'')).map(f=>`<div class="filing-node"><button class="btn small ${String(f.id)===String(filingFolder)?'':'outline'}" data-folder="${f.id}">${esc(f.name)}${Number(f.restricted)?' · Restricted':''}</button>${children(f.id,level+1)}</div>`).join('');v.innerHTML=`<section class="command-head"><div><div class="ims-kicker">Records / private storage</div><h2>File workspace</h2><p>Folder access, file revisions and integrity records.</p></div>${me.role==='admin'?'<button class="btn" id="filing-new-folder">New folder</button> <button class="btn" id="filing-init">Initialize corporate folders</button>':''}</section><div class="filing-layout"><section class="ims-panel"><h3>Directories</h3><button class="btn outline small" data-folder="">Root</button>${children()||'<p>No folders available.</p>'}</section><section class="ims-panel"><h3>${esc(selected?.name||'Select a folder')}</h3>${selected?`<div class="toolbar"><input id="filing-search" placeholder="Filter files" aria-label="Filter files"><button class="btn small" id="filing-upload">Upload file</button>${me.role==='admin'?'<button class="btn small" id="filing-acl">Permissions</button>':''}</div>${table(['File','Revision','Size','Actions'],rows.map(r=>`<tr data-file-row><td>${esc(r.title)}<br><small>${esc(r.filename)}</small></td><td>${r.revision}</td><td>${Math.ceil(r.bytes/1024)} KiB</td><td><a class="btn small outline" href="/api/admin/ims/filing/versions/${r.version_id}/download">Download</a> <button class="btn small" data-file="${r.id}">New revision</button></td></tr>`))}`:'<p>Choose a directory or create one at the root.</p>'}<p class="ims-muted">Private file revisions are not approved controlled documents. Use Document Control for formal approval. Workspace quota 100 MiB; 5 MiB per file.</p></section></div>`;if(v.querySelector('#filing-init'))v.querySelector('#filing-init').onclick=async e=>{e.currentTarget.disabled=true;try{await api(filingPath+'initialize','POST',{});await load('filing');}catch(err){toast(err.message,true);e.currentTarget.disabled=false;}};v.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{filingFolder=b.dataset.folder||null;load('filing');});if(v.querySelector('#filing-search'))v.querySelector('#filing-search').oninput=e=>v.querySelectorAll('[data-file-row]').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if(v.querySelector('#filing-new-folder'))v.querySelector('#filing-new-folder').onclick=()=>{showModal('Create directory',`<form id="edit-form">${field('name','Folder name','text','',true)}${select('restricted','Access',[['true','Restricted — explicit manager grants'],['false','All management users (subject to parent permissions)']])}${formActions('Create folder')}</form>`);bindModal(filingPath+'folders','POST',x=>({name:x.name,parent_id:filingFolder?Number(filingFolder):null,restricted:x.restricted==='true'}),'filing');};if(v.querySelector('#filing-acl'))v.querySelector('#filing-acl').onclick=()=>{showModal('Folder permissions',`<p>Administrator access is inherent. Restricted ancestors also require grants. Current grants:</p>${table(['Manager','Access'],t.grants.filter(g=>String(g.folder_id)===String(selected.id)).map(g=>`<tr><td>${esc(t.users.find(u=>String(u.id)===String(g.user_id))?.name||g.user_id)}</td><td>${esc(g.permission)}</td></tr>`))}<form id="edit-form">${select('user_id','Manager',t.users.map(u=>[u.id,u.name]))}${select('permission','Permission',['read','write','none'])}${formActions('Save permission')}</form>`);bindModal(filingPath+'folders/'+selected.id+'/permissions','POST',x=>({user_id:Number(x.user_id),permission:x.permission}),'filing');};if(v.querySelector('#filing-upload'))v.querySelector('#filing-upload').onclick=()=>filingUpload(selected.id);v.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>filingUpload(selected.id,b.dataset.file));}
function filingUpload(folder,fileId){showModal(fileId?'Upload revision':'Upload file',`<form id="filing-upload-form">${fileId?'':field('title','File title','text','',true)}<div class="field"><label for="filing-file">File (PDF, DOCX, XLSX, TXT; 5 MiB)</label><input type="file" id="filing-file" accept=".pdf,.docx,.xlsx,.txt" required></div>${formActions('Save file')}</form>`);const f=document.querySelector('#filing-upload-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{const file=f.querySelector('#filing-file').files[0];if(!file||file.size>5*1024*1024)throw Error('Choose a file up to 5 MiB');operationalState('Validating file…');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api(filingPath+(fileId?'files/'+fileId+'/versions':'folders/'+folder+'/files'),'POST',{...Object.fromEntries(new FormData(f)),filename:file.name,base64});closeModal();operationalState('File revision recorded.',true);await load('filing');}catch(e){f.querySelector('#form-notice').textContent=e.message;f.querySelector('#form-notice').className='message error';operationalState('File not saved.',true);}finally{b.disabled=false;}};}
